#include <memory>
#include <variant>

struct Num { double v; };
struct Add { std::unique_ptr<struct Node> l, r; };
struct Mul { std::unique_ptr<struct Node> l, r; };
struct Node { std::variant<Num, Add, Mul> alt; };

double eval(const Node& n) {
    return std::visit(overloaded{
        [](const Num& x) { return x.v; },
        [](const Add& a) { return eval(*a.l) + eval(*a.r); },
        [](const Mul& m) { return eval(*m.l) * eval(*m.r); },
    }, n.alt);
}

#include <execution>
#include <numeric>
#include <vector>

long parallel_total(const std::vector<long>& xs) {
    return std::reduce(std::execution::par, xs.begin(), xs.end(), 0L,
                       [](long a, long b) { return a + b; });
}
